def transform(grid):
    if not grid:
        return grid
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Count occurrences
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    # Background is the most frequent value
    background = max(counts, key=counts.get)

    # Separator is the second most frequent value
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    separator = sorted_counts[1][0] if len(sorted_counts) > 1 else background

    # Identify marker rows and columns
    marker_rows = []
    for i in range(rows):
        row_vals = grid[i]
        if any(val != background and val != separator for val in row_vals):
            marker_rows.append(i)

    marker_cols = []
    for j in range(cols):
        col_vals = [grid[i][j] for i in range(rows)]
        if any(val != background and val != separator for val in col_vals):
            marker_cols.append(j)

    # Create output grid with dimensions (len(marker_rows) x len(marker_cols))
    output = [[0] * len(marker_cols) for _ in range(len(marker_rows))]
    for i, mr in enumerate(marker_rows):
        for j, mc in enumerate(marker_cols):
            output[i][j] = grid[mr][mc]

    return output
