def transform(grid):
    if not grid or not grid[0]:
        return []

    from collections import Counter
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]

    markers = set()
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                markers.add((r, c))

    marker_rows = sorted(set(r for r, c in markers))
    marker_cols = sorted(set(c for r, c in markers)) if markers else []

    if not marker_rows or not marker_cols:
        return [[background] * (mark * [] + [mark]) for mark in [1]] if markers else []

    output = [[background] * len(marker_cols) for _ in range(len(marker_rows))]
    for i, mr in enumerate(marker_rows):
        for j, mc in enumerate(marker_cols):
            if (mr, mc) in markers:
                val = grid[mr][mc]
                output[i][j] = val

    return output
